export async function nitroBadge(){if(badge)return badge;if(!imagePromise)imagePromise=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src='assets/platforms/skoda.svg';});const image=await imagePromise,c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');const glow=x.createRadialGradient(256,256,168,256,256,256);glow.addColorStop(0,'#e8fffacc');glow.addColorStop(.45,'#68ffd68a');glow.addColorStop(1,'#41ffcc00');x.fillStyle=glow;x.fillRect(0,0,512,512);x.save();x.beginPath();x.arc(256,256,202,0,Math.PI*2);x.clip();x.drawImage(image,54,54,404,404);x.restore();x.strokeStyle='#d6fff2';x.shadowColor='#4bffd2';x.shadowBlur=28;x.lineWidth=6;x.beginPath();x.arc(256,256,207,0,Math.PI*2);x.stroke();badge=c;return c;}
export function drawNitroBadge(ctx,race,x,y,size){if(!nitroVisible(race)||size<4)return;ctx.save();const pulse=1+Math.sin(race.elapsed*4)*.04;size*=pulse;ctx.shadowColor='#55ffd5';ctx.shadowBlur=Math.min(24,size*.14);if(badge)ctx.drawImage(badge,x-size/2,y-size/2,size,size);else{ctx.strokeStyle='#b8fff0';ctx.lineWidth=Math.max(2,size*.05);ctx.beginPath();ctx.arc(x,y,size*.4,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e9fff8';ctx.font='bold '+Math.max(8,size*.14)+'px Arial';ctx.textAlign='center';ctx.fillText('ŠKODA',x,y);}ctx.restore();}
